#include "../Source/DSP/AnalysisPluginCore.h"
#include <iostream>
#include <random>
#include <thread>
#include <cstdlib>
#include <new>
static thread_local bool checking=false;
static std::atomic<unsigned> allocations{0};
void* operator new(std::size_t n){if(checking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void* operator new[](std::size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
static void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
using namespace hem::analysis;
static void feed(LoudnessCore&core,double rate,double seconds,float amplitude,double hz=997,bool stereo=true){std::array<float,512> l{},r{};const int total=int(std::llround(rate*seconds));for(int o=0;o<total;o+=512){const int n=std::min(512,total-o);for(int i=0;i<n;++i){l[size_t(i)]=amplitude*float(std::sin(2*hem::pi*hz*(o+i)/rate));r[size_t(i)]=stereo?l[size_t(i)]:0;}core.push(l.data(),r.data(),n);}}
int main(){try{
 auto loud=std::make_unique<LoudnessCore>();
 for(double rate:{44100.,48000.,96000.}){loud->prepare(rate);feed(*loud,rate,3.2f,.1f);auto f=loud->calculate();require(f.integratedReady&&f.shortReady,"loudness warmup");require(std::abs(f.integrated+20)<.08,"997 Hz stereo LUFS calibration");require(std::abs(f.shortTerm+20)<.08,"short term calibration");require(f.momentaryReady&&std::abs(f.momentary+20)<.08,"momentary calibration");require(f.correlationReady&&f.correlation>.999f,"correlation");require(std::abs(f.crest-3.0103f)<.1f,"crest");require(std::abs(f.vu[0]+5.0103f)<.1f,"VU calibration");}
 loud->prepare(48000);feed(*loud,48000,3.2,.1f,997,false);require(std::abs(loud->calculate().integrated+23.0103)<.08,"mono power is not stereo duplicated");
 loud->reset();feed(*loud,48000,1,0);require(!loud->calculate().integratedReady,"silence gated");feed(*loud,48000,4,.1f);const auto gated=loud->calculate().integrated;feed(*loud,48000,3,0);require(std::abs(loud->calculate().integrated-gated)<.5,"absolute and relative gating");feed(*loud,48000,5,.001f);require(std::abs(loud->calculate().integrated-gated)<.6,"relative gate excludes quiet audible blocks");loud->discontinuity();require(!loud->calculate().integratedReady&&!loud->calculate().complete,"discontinuity invalidates integrated");
 // EBU Tech 3342 generated minimum-requirement signals #1–4, not official downloaded audio.
 for(const auto levels:std::vector<std::vector<float>>{{-20,-30},{-20,-15},{-40,-20},{-50,-35,-20,-35,-50}}){loud->reset();for(float level:levels)feed(*loud,48000,20,std::pow(10.f,level/20),1000);const float expected=levels.size()==5?15:std::abs(levels[0]-levels[1]);auto f=loud->calculate();require(f.lraReady&&std::abs(f.lra-expected)<1,"EBU generated LRA fixture");}
 // EBU Tech 3341 steady tapered intersample-peak fixtures #15–19.
 for(const auto pair:std::vector<std::pair<double,double>>{{4,0},{4,45},{6,60},{8,67.5}}){loud->reset();std::vector<float>a(48000);for(size_t i=0;i<a.size();++i){const double fade=std::min({1.,double(i)/480,double(a.size()-1-i)/480});a[i]=float(.5*fade*std::sin(2*hem::pi*i/pair.first+pair.second*hem::pi/180));}loud->push(a.data(),a.data(),int(a.size()));require(std::abs(loud->calculate().truePeakEstimate+6.0206)<.25,"8x reconstruction intersample fixture");}
 std::cout<<"PASS loudness: 3 rates, stereo/mono, M/S/I, silence/gates, correlation, crest, VU, generated EBU LRA 1–4 and peak 15–18\n";
 auto spectrum=std::make_unique<SpectrumCore>();
 for(double rate:{8000.,44100.,48000.,96000.,192000.})for(int order=9;order<=13;++order)for(int window=0;window<3;++window){spectrum->prepare(rate);SpectrumSettings s;s.order=order;s.window=window;s.averagingMs=0;spectrum->configure(s);int n=1<<order;std::vector<float>l(size_t(n),0),r(size_t(n),0);for(int i=0;i<n;++i){l[size_t(i)]=.5f*float(std::sin(2*hem::pi*37*i/n));r[size_t(i)]=-l[size_t(i)];}spectrum->push(l.data(),r.data(),n,[](const auto&){});const auto&f=spectrum->latest();require(f.valid&&std::abs(f.db[37]+6.0206)<.025,"FFT amplitude/window coherent gain");require(std::abs(f.peakHz-float(37*rate/n))<.01,"FFT frequency mapping");require(std::abs(f.timeSeconds-n/rate)<1.e-8,"FFT timestamp");}
 spectrum->prepare(48000);SpectrumSettings settings;settings.order=9;settings.window=0;settings.averagingMs=0;settings.rms=true;spectrum->configure(settings);std::array<float,512>a{},b{};for(int i=0;i<512;++i)a[size_t(i)]=b[size_t(i)]=.5f*float(std::sin(2*hem::pi*32*i/512));spectrum->push(a.data(),b.data(),512,[](const auto&){});require(std::abs(spectrum->latest().db[32]+9.0309)<.02,"FFT RMS calibration");settings.channel=4;spectrum->configure(settings);spectrum->push(a.data(),b.data(),512,[](const auto&){});require(spectrum->latest().peakDb==floorDb,"side null");
 std::cout<<"PASS FFT: 5 rates × 5 sizes × 3 windows, stereo antiphase preservation, frequency/time axes, RMS and side null\n";
 DeltaCore delta;delta.prepare(48000);const int latency=delta.latency();std::vector<float>x(4096),y(4096),d(4096);std::mt19937 rng(3);std::uniform_real_distribution<float>dist(-.2f,.2f);for(auto&v:d)v=dist(rng);x=y=d;DeltaSettings ds;ds.mode=2;ReferenceBlock ref{d.data(),d.data(),4096,48000,0,true};checking=true;delta.process(x.data(),y.data(),4096,ref,ds,[](auto...){ });checking=false;for(size_t i=700;i<x.size();++i)require(std::abs(x[i])<1.e-7,"aligned delta null");require(delta.latest().referenceValid,"valid reference");
 delta.prepare(48000);x=y=d;ref.valid=false;delta.process(x.data(),y.data(),4096,ref,ds,[](auto...){ });require(!delta.latest().referenceValid,"missing reference unavailable");for(size_t i=size_t(latency);i<x.size();++i)require(x[i]==d[i-size_t(latency)],"missing reference latency-correct processed passthrough");
 std::vector<float>delayed(4096);for(size_t i=17;i<d.size();++i)delayed[i]=d[i-17];const auto alignment=DeltaCore::align(d.data(),delayed.data(),4096,64);require(alignment.valid&&alignment.lag==17,"real stream auto alignment");std::fill(delayed.begin(),delayed.end(),0);require(!DeltaCore::align(d.data(),delayed.data(),4096,64).valid,"silent reference not aligned");
 auto queue=std::make_unique<Transport<2,2>>();std::array<const float*,2>ptrs{d.data(),d.data()};checking=true;queue->push(ptrs,1000);checking=false;require(queue->dropped()==488,"queue overflow counted");std::uint64_t first=0;int packets=0;while(queue->consume([&](const auto&p){require(p.first==first,"transport timeline");first+=p.count;++packets;})){}require(packets==2,"bounded transport");require(allocations==0,"callback allocation");
 delta.prepare(48000);x=y=d;ref.valid=true;ds.delayTrimMs=ds.monitorGainDb=std::numeric_limits<float>::quiet_NaN();delta.process(x.data(),y.data(),4096,ref,ds,[](auto...){ });for(float v:x)require(std::isfinite(v),"nonfinite Delta control poisoned output");settings.averagingMs=settings.historySeconds=settings.rangeDb=std::numeric_limits<float>::quiet_NaN();spectrum->configure(settings);spectrum->push(a.data(),b.data(),512,[](const auto&){});require(std::isfinite(spectrum->latest().peakDb),"nonfinite spectrum control poisoned frame");
 std::cout<<"PASS Delta and transport: true two-stream null, missing route, fixed latency, real auto alignment, silent rejection, overflow and zero allocations\n";
 return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
